const object=(v:unknown):v is Record<string,unknown>=>typeof v==="object"&&v!==null&&!Array.isArray(v);
export async function POST(request:Request){if(process.env.ORGANY_RUNTIME!=="db")return NextResponse.json({error:"Reference antiphon DB runtime is not enabled."},{status:400});if(!process.env.DATABASE_URL)return NextResponse.json({error:"DATABASE_URL is required."},{status:500});let body:unknown;try{body=await request.json();}catch{return NextResponse.json({error:"Malformed JSON body."},{status:400});}if(!object(body)||(body.action!=="list"&&body.action!=="getById")||!object(body.input))return NextResponse.json({error:"Unsupported reference antiphon request."},{status:400});const input=body.input;if(body.action==="getById"){if(Object.keys(input).length!==1||typeof input.id!=="string"||!/^(?:czech|polish):[1-9]\d*$/.test(input.id))return NextResponse.json({error:"Valid antiphon ID is required."},{status:400});}else{const allowed=new Set(["language","search","page","pageSize"]);if(Object.keys(input).some(k=>!allowed.has(k))||(input.language!==undefined&&!['all','czech','polish'].includes(input.language as string))||(input.search!==undefined&&(typeof input.search!=="string"||input.search.length>200))||(input.page!==undefined&&(!Number.isInteger(input.page)||Number(input.page)<0))||(input.pageSize!==undefined&&(!Number.isInteger(input.pageSize)||Number(input.pageSize)<1||Number(input.pageSize)>200)))return NextResponse.json({error:"Invalid antiphon query."},{status:400});}const pool=getAppDbPool();try{const provider=new PostgresReferenceAntiphonProvider(pool);if(body.action==="list")return NextResponse.json(await provider.list(input as ReferenceAntiphonQuery));const found=await provider.getById(input.id as string);return found?NextResponse.json(found):NextResponse.json({error:"Reference antiphon not found."},{status:404});}catch(error){return NextResponse.json({error:error instanceof Error?error.message:"Reference antiphon API failed."},{status:500});}}

import { NextResponse } from "next/server";
import { PostgresReferenceCatalogProvider } from "../../../src/application/postgres-reference-catalog";
import type { ReferenceCatalogQuery } from "../../../src/application/reference-catalog-contract";
import { getAppDbPool } from "../../../src/db/app-pool";

type ReferenceAction = "list" | "getById";

export async function POST(request: Request) {
  if (process.env.ORGANY_RUNTIME !== "db") return NextResponse.json({ error: "Reference catalog DB runtime is not enabled." }, { status: 400 });
  if (!process.env.DATABASE_URL) return NextResponse.json({ error: "DATABASE_URL is required for reference catalog DB runtime." }, { status: 500 });

  let body: { action?: unknown; input?: unknown };
  try { body = await request.json() as { action?: unknown; input?: unknown }; }
  catch { return NextResponse.json({ error: "Malformed JSON body." }, { status: 400 }); }
  if (body.action !== "list" && body.action !== "getById") return NextResponse.json({ error: "Unsupported reference catalog action." }, { status: 400 });
  const error = validateInput(body.action, body.input);
  if (error) return NextResponse.json({ error }, { status: 400 });

  const pool = getAppDbPool();
  try {
    const provider = new PostgresReferenceCatalogProvider(pool);
    if (body.action === "list") return NextResponse.json(await provider.list(body.input as ReferenceCatalogQuery));
    const record = await provider.getById((body.input as { id: string }).id);
    return record ? NextResponse.json(record) : NextResponse.json({ error: "Reference catalog record not found." }, { status: 404 });
  } catch (caught) {
    return NextResponse.json({ error: caught instanceof Error ? caught.message : "Reference catalog API failed." }, { status: 500 });
  }
}

function validateInput(action: ReferenceAction, input: unknown): string | undefined {
  if (!isRecord(input)) return "Input object is required.";
  if (action === "getById") {
    if (Object.keys(input).some((key) => key !== "id")) return "Unsupported getById input field.";
    return typeof input.id === "string" && /^(czech|polish):[1-9]\d*$/.test(input.id) ? undefined : "Valid stable reference ID is required.";
  }
  const allowed = new Set(["language", "search", "page", "pageSize"]);
  if (Object.keys(input).some((key) => !allowed.has(key))) return "Unsupported list input field.";
  if (input.language !== undefined && !["all", "czech", "polish"].includes(input.language as string)) return "Valid reference language is required.";
  if (input.search !== undefined && (typeof input.search !== "string" || input.search.length > 200)) return "Search must be a string of at most 200 characters.";
  if (input.page !== undefined && (!Number.isInteger(input.page) || (input.page as number) < 0)) return "Page must be a non-negative integer.";
  if (input.pageSize !== undefined && (!Number.isInteger(input.pageSize) || (input.pageSize as number) < 1 || (input.pageSize as number) > 200)) return "Page size must be an integer from 1 to 200.";
  return undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> { return typeof value === "object" && value !== null && !Array.isArray(value); }

import { NextResponse } from "next/server";
import { PostgresReferenceThematicSectionProvider } from "../../../src/application/postgres-reference-thematic-section";
import { getAppDbPool } from "../../../src/db/app-pool";

const object = (value: unknown): value is Record<string, unknown> => typeof value === "object" && value !== null && !Array.isArray(value);
const language = (value: unknown): value is "czech" | "polish" => value === "czech" || value === "polish";

export async function POST(request: Request) {
  if (process.env.ORGANY_RUNTIME !== "db") return NextResponse.json({ error: "Reference Topic DB runtime is not enabled." }, { status: 400 });
  if (!process.env.DATABASE_URL) return NextResponse.json({ error: "DATABASE_URL is required." }, { status: 500 });
  let body: unknown;
  try { body = await request.json(); } catch { return NextResponse.json({ error: "Malformed JSON body." }, { status: 400 }); }
  if (!object(body) || !["listSections", "getSectionById", "resolveSection"].includes(String(body.action)) || !object(body.input)) {
    return NextResponse.json({ error: "Unsupported reference Topic request." }, { status: 400 });
  }
  const input = body.input;
  if (body.action === "listSections") {
    if (Object.keys(input).length !== 1 || !language(input.language)) return NextResponse.json({ error: "Valid Topic language is required." }, { status: 400 });
  } else if (body.action === "getSectionById") {
    if (Object.keys(input).length !== 1 || typeof input.id !== "string" || !/^(?:czech|polish):[a-z0-9][a-z0-9:-]*$/.test(input.id)) return NextResponse.json({ error: "Valid Topic ID is required." }, { status: 400 });
  } else {
    if (Object.keys(input).length !== 2 || !language(input.language) || !Number.isInteger(input.canonicalSongNumber) || Number(input.canonicalSongNumber) <= 0) return NextResponse.json({ error: "Valid Topic resolution input is required." }, { status: 400 });
  }
  const pool = getAppDbPool();
  try {
    const provider = new PostgresReferenceThematicSectionProvider(pool);
    if (body.action === "listSections") return NextResponse.json(await provider.listSections(input.language as "czech" | "polish"));
    if (body.action === "getSectionById") {
      const found = await provider.getSectionById(input.id as string);
      return found ? NextResponse.json(found) : NextResponse.json({ error: "Reference Topic not found." }, { status: 404 });
    }
    const found = await provider.resolveSection(input.language as "czech" | "polish", Number(input.canonicalSongNumber));
    return found ? NextResponse.json(found) : NextResponse.json({ error: "Reference Topic not found." }, { status: 404 });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Reference Topic API failed." }, { status: 500 });
  }
}

/* Issue #253/#255/#257/#259: compact Audit History service-state summaries and diffs. */

.audit-history-card {
  gap: 0.55rem;
}

.audit-event-list {
  display: grid;
  gap: 0.5rem;
}

.audit-event {
  background: #f8fafc;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  display: grid;
  gap: 0.16rem;
  min-width: 0;
  padding: 0.4rem 0.55rem;
}

.audit-section-rule {
  border-top: 1px solid #d9e0e8;
  height: 0;
  margin: 0.14rem 0 0.12rem;
  width: 100%;
}

.audit-event-header {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  font-size: 0.84rem;
  gap: 0.22rem;
  line-height: 1.35;
  margin: 0;
  min-width: 0;
}

.audit-state-line {
  align-items: start;
  display: grid;
  font-size: 0.82rem;
  gap: 0.22rem;
  grid-template-columns: 3.15rem minmax(0, 1fr);
  line-height: 1.35;
  margin: 0;
  min-width: 0;
}

.audit-state-label {
  white-space: nowrap;
}

.audit-service-state {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
  width: 100%;
}

.audit-service-primary,
.audit-service-secondary {
  align-items: baseline;
  display: grid;
  gap: 0.85rem;
  grid-template-columns: minmax(0, 1fr) auto;
  min-width: 0;
  width: 100%;
}

.audit-service-primary-left,
.audit-service-primary-right {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 0.22rem;
  min-width: 0;
}

.audit-service-primary-right {
  flex-wrap: nowrap;
  justify-self: end;
  white-space: nowrap;
}

.audit-state-field-group {
  align-items: baseline;
  display: inline-flex;
  gap: 0.22rem;
}

.audit-lifecycle-slot {
  justify-self: end;
  white-space: nowrap;
}

.audit-separator {
  color: var(--muted);
}

.audit-state-muted {
  color: #98a2b3;
}

.audit-state-changed {
