.catalog-organist-language-row > * {
  min-width: 0;
}

.catalog-context-cell {
  align-content: start;
  display: grid;
  gap: 0.35rem;
  min-width: 0;
  position: relative;
}

.catalog-context-label {
  color: var(--muted);
  font-weight: 600;
}

.reference-song-lookup {
  min-width: 0;
  position: relative;
}

.reference-song-control {
  align-items: center;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  display: grid;
  min-width: 0;
}

.reference-song-control:focus-within {
  outline: 2px solid #84adff;
  outline-offset: 1px;
}

.reference-song-control input {
  border: 0;
  min-width: 0;
  outline: 0;
}

.reference-song-listbox {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  box-shadow: 0 0.75rem 1.5rem rgb(31 41 51 / 12%);
  direction: rtl;
  left: 0;
  margin-top: 0.35rem;
  max-height: min(32rem, 70vh);
  overflow-y: auto;
  position: absolute;
  right: 0;
  top: 100%;
  z-index: 70;
}

.reference-song-listbox > * {
  direction: ltr;
}

.reference-song-option {
  align-items: center;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  display: grid;
  gap: 0.5rem;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 2.5rem;
  padding: 0.35rem 0.45rem;
  scroll-margin-block: 0.35rem;
}

.reference-song-option:last-child {
  border-bottom: 0;
}

.reference-song-option-active {
  border-radius: 0.55rem;
  outline: 3px solid #84adff;
  outline-offset: -3px;
}

.reference-song-option[aria-selected="true"] {
  background: #eff6ff;
}

.reference-song-list-state {
  color: var(--muted);
  padding: 0.65rem 0.75rem;
}

.reference-song-list-error {
  color: var(--danger);
}

.catalog-availability-switch {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: flex-start;
}

.catalog-availability-switch .active-workspace,
.catalog-view-switch .active-workspace {
  background: var(--foreground);
  color: #fff;
}

.catalog-candidate-panel {
  gap: 0.65rem;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  padding: 0.75rem;
  width: 100%;
}

.catalog-candidate-header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: space-between;
}

.catalog-view-switch {
  flex-direction: row;
}

.catalog-candidate-scroll {
  direction: rtl;
  display: grid;
  max-height: 18rem;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-left: 0.35rem;
}

.catalog-candidate-scroll > * {
  direction: ltr;
}

.catalog-candidate-row {
  min-width: 0;
  padding: 0.25rem 0.35rem;
  position: relative;
}

.catalog-candidate-summary {
  min-width: 0;
  overflow-x: auto;
  white-space: nowrap;
}

.catalog-candidate-summary > .candidate-option-main {
  align-items: center;
  min-height: 2rem;
  min-width: max-content;
}

.catalog-candidate-state {
  color: var(--muted);
  margin: 0;
  padding: 0.65rem 0.75rem;
}

.catalog-candidate-row > .melody-detail-candidate {
  justify-self: end !important;
  margin-top: 0 !important;
  max-height: min(32rem, 70vh);
  overflow-y: auto;
  position: absolute !important;
  right: 0;
  top: 0;
  transform: none !important;
  width: min(82%, 46rem) !important;
  z-index: 50 !important;
}

.melody-personal-preference {
  align-items: center;
  display: grid;
  gap: 0.4rem;
  grid-template-columns: minmax(0, 1fr) 3.25rem;
  margin-left: auto;
  width: 13rem;
}

.melody-personal-preference > span {
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 700;
  white-space: nowrap;
}

.melody-personal-preference > select {
  height: 2rem;
  min-width: 3.25rem;
  padding: 0.2rem 0.35rem;
  width: 3.25rem;
}

/* Stage 6 refinement: fixed three-row admin Reference melody-edge editor. */
.catalog-melody-edge-editor {
  gap: 0.65rem;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  padding: 0.75rem;
}

.catalog-melody-edge-language-row,
.catalog-melody-edge-song-row {
  display: grid;
  gap: 0.75rem;
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.catalog-melody-edge-language-row > select {
  font-weight: 700;
  justify-self: start;
  max-width: 100%;
  min-width: 7rem;
  width: calc(100% - 4.5rem);
}

.catalog-melody-edge-song-row > * {
  min-width: 0;
}

.melody-edge-selected-value {
  font-weight: 700;
}

.catalog-melody-edge-actions {
  display: flex;
  gap: 0.4rem;
  grid-column: 1 / -1;
  justify-content: flex-start;
}

.catalog-melody-edge-editor > .catalog-candidate-state {
  grid-column: 1 / -1;
}

.reference-song-option-outside-melody {
  background: #f3f4f6;
  color: var(--muted);
}

@media (max-width: 720px) {
  .catalog-context {
    grid-template-columns: minmax(0, 1fr);
  }

  .catalog-candidate-header {
    align-items: stretch;
    display: grid;
  }

  .catalog-melody-edge-language-row > select {
    min-width: 0;
    width: calc(100% - 2rem);
  }
}


/* Issue #310: optional WhatsApp handoff only after successful plan finalization. */
.post-finalize-dialog-backdrop {
  align-items: center;
  background: rgb(31 41 51 / 34%);
  display: flex;
  inset: 0;
  justify-content: center;
  padding: 1rem;
  position: fixed;
  z-index: 120;
}

.post-finalize-dialog {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 1rem;
  box-shadow: 0 1.5rem 3rem rgb(31 41 51 / 20%);
  display: grid;
  gap: 0.85rem;
  max-width: 26rem;
  padding: 1.25rem;
  width: 100%;
}

.post-finalize-dialog p {
  color: var(--muted);
  margin: 0;
}

.post-finalize-dialog-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.post-finalize-dialog-actions a {
  background: var(--foreground);
  border: 1px solid var(--foreground);
  border-radius: 999px;
  color: #fff;
  font-weight: 700;
  padding: 0.6rem 0.9rem;
  text-decoration: none;
}

